def standard_deviation(numbers): 
    avg = sum(numbers) / len(numbers)
    var = 0
    for num in numbers:
        var += (num - avg)**2
    return (var/len(numbers))**0.5

"""
Algorithm to sort an array of numbers into ascending order
"""

def sort_ascending(nums):
    sorted_list = []
    while nums:
        lowest = nums[0]
        for num in nums:
            if num < lowest:
                lowest = num
        sorted_list.append(lowest)
        nums.remove(lowest)

    return sorted_list

